[171] = { en = "A Warden of the Alliance", tier = 4,
  t = "Een beschermer van de Alliance",
  d = "Je bent zo ontzettend lief voor me geweest, $N. Ik had nooit gedacht dat ik zoveel plezier zou hebben tijdens Children's Week. Dank je wel. Ik wil niet verdrietig zijn over wat er met me gebeurd is en zo - mijn ouders zeiden altijd dat ik sterker moest zijn dan alle nare dingen die gebeuren. Weet je, als ik groot ben, wil ik een held worden... net als jij.$B$BHet spijt me dat ik het moet zeggen, maar het is tijd om naar huis te gaan. Laten we teruggaan, dan vertel ik de directrice wat een geweldig persoon jij bent!",
  o = "Breng je pupil terug naar het weeshuis van Stormwind door de Human Orphan Whistle in te leveren bij Orphan Matron Nightingale in het Cathedral District.",
  p = "Fijn je weer te zien, $N. Heb je de taken gedaan waarvoor je je tijdens Children's Week hebt aangemeld?",
  c = "Moge de hemel je zegenen, $N. Je hebt meer voor Randis gedaan dan de meeste mensen ooit voor hem zouden doen. Dank je - je bent een stralende ster aan de hemel van de Alliance.$b$bAlsjeblieft - als je tijd hebt, kom ons dan nog eens bezoeken. Ik weet dat Randis dat leuk zou vinden, en ik ook.",
  g = { {"beschermer", "warden, protector"}, {"ontzettend", "terribly, very"}, {"verdrietig", "sad"}, {"nare", "bad, nasty (naar)"}, {"directrice", "matron, head (f.)"}, {"pupil", "ward"}, {"weeshuis", "orphanage"}, {"in te leveren", "to hand in (inleveren)"}, {"aangemeld", "volunteered, signed up (zich aanmelden)"}, {"moge de hemel je zegenen", "may the heavens bless you"}, {"stralende", "shining (stralend)"} },
},

[558] = { en = "Jaina's Autograph", tier = 4,
  t = "Jaina's handtekening",
  d = "Ze zeggen dat Lady Jaina Proudmoore in Theramore een van de grootste helden is die de Alliance ooit heeft gehad. Als ik groot ben, wil ik ook een held van de Alliance worden!$B$BKen jij Jaina, $N? Wil je me alsjeblieft een plezier doen? Kun je haar handtekening voor me halen? Ik weet niet hoe ik het haar moet vragen, en ze heeft vast geen tijd voor iemand zoals ik... maar jij! Jij bent een avonturier, net als zij! Ik wed dat ze jou zo haar handtekening geeft!$B$BAlsjeblieft?",
  o = "Reis naar Theramore en kijk of je Lady Jaina Proudmoore's handtekening kunt krijgen voor je pupil.",
  p = "Later wil ik net zo'n held worden als Jaina... nou ja, een jongensheld dan.",
  c = "WOW! Je hebt de handtekening van Lady Jaina voor me! Heel erg bedankt! En wow... ze heeft er een persoonlijk berichtje op geschreven - voor mij! Ik wist wel dat ze echt cool zou zijn, en misschien bedank ik haar ooit zelf... als ik een held van de Alliance word!$B$BJij bent de beste, $N. Bedankt dat je zo lief voor me bent.",
  g = { {"handtekening", "autograph, signature"}, {"een plezier doen", "to do a favour"}, {"avonturier", "adventurer"}, {"ik wed", "I bet (wedden)"}, {"pupil", "ward"}, {"jongensheld", "boy hero"}, {"persoonlijk", "personal"}, {"berichtje", "little message"} },
},

[1468] = { en = "Children's Week", tier = 4,
  t = "Children's Week",
  d = "Wil je ons hier in het weeshuis helpen? Je bent een zegen, vriend; je hulp tijdens Children's Week is onmisbaar.$B$BNeem dit fluitje. Je kunt het maar korte tijd gebruiken - meestal niet langer dan Children's Week zelf. Als je het gebruikt, kun je praten met het kind waarvoor je beloofd hebt te zorgen. Als je het nog een keer gebruikt, stuur je het kind weg.$B$BGa vooral je gang, $N - gebruik het fluitje en ontmoet je pupil! Ik weet zeker dat het kind je heel graag wil ontmoeten.",
  o = "Gebruik de Human Orphan Whistle om te praten met het kind waarvoor je tijdens Children's Week zorgt.",
  c = "Eh... hoi. Ik heet Randis, en ik denk dat jij voor me gaat zorgen? Je bent een avonturier, net als mijn mama en papa waren. Ik ben blij je te ontmoeten.$B$BIk hoop dat we samen veel plezier hebben. Er zijn een paar dingen die ik graag wil doen, en de directrice zegt dat je deze week een soort grote $gbroer:zus; voor me bent. Dat zou ik heel erg fijn vinden, ja $gmeneer:mevrouw;.",
  g = { {"weeshuis", "orphanage"}, {"zegen", "blessing"}, {"onmisbaar", "invaluable, indispensable"}, {"fluitje", "whistle"}, {"meestal", "usually"}, {"stuur weg", "send away, dismiss (wegsturen)"}, {"ga vooral je gang", "by all means, go ahead"}, {"pupil", "ward"}, {"directrice", "matron, head (f.)"} },
},

[1479] = { en = "The Bough of the Eternals", tier = 4,
  t = "De Bough of the Eternals",
  d = "Ik heb verhalen gehoord dat de nachtelfen hun bank in een boom hebben - een boom die op een beer lijkt! Dat is zo cool! Nachtelfen zijn leuk, omdat ze van de natuur houden en zo, maar beren zijn gewoon superleuk!$B$BWil je me alsjeblieft meenemen naar de berenboom in Darnassus? Er gaat een boot die ons daar dichtbij brengt, en het duurt vast niet lang. Alsjeblieft, alsjeblieft, alsjeblieft!",
  o = "Breng de wees naar de bank van Darnassus. De bank zelf is uitgehold in een boom die de Bough of the Eternals heet.",
  p = "Zijn we er al?",
  c = "Wow, dat is nog cooler dan ik dacht - de Bough of the Eternals! Ik dacht niet dat hij zo groot zou zijn, maar hij is echt zo groot! Zag je die vogel er bovenop ook?! Ik vraag me af hoe ze de takken er zo uit hebben laten zien!$B$BBedankt dat je me naar Darnassus hebt gebracht, $N. Je bent geweldig!",
  e = "Ga naar de bank in Darnassus, ook wel de Bough of the Eternals genoemd.",
  g = { {"nachtelfen", "night elves (nachtelf)"}, {"superleuk", "totally awesome"}, {"berenboom", "bear-tree"}, {"dichtbij", "close by"}, {"wees", "orphan"}, {"uitgehold", "hollowed out (uithollen)"}, {"bovenop", "on top"}, {"ik vraag me af", "I wonder (zich afvragen)"}, {"takken", "branches (tak)"}, {"ook wel genoemd", "also known as"} },
},

[1558] = { en = "The Stonewrought Dam", tier = 4,
  t = "De Stonewrought Dam",
  d = "In Ironforge wonen alle dwergen en gnomen. Daar vlakbij is een plek die Loch Modan heet, en de dwergen hebben daar een ENORME dam gebouwd. Ze zeggen dat het een van de grootste dingen is die iemand ooit heeft gemaakt. Wow!$B$BKun je me alsjeblieft naar Loch Modan brengen om de dam te zien? Ik denk dat hij de Stone... eh... Stonewrench Dam heet? Stonewrought? Hij is groot - dat is zeker. Ik wil graag uitkijken over de grote waterval. Ik beloof dat ik niet te ver voorover leun!",
  o = "Breng de wees naar de Stonewrought Dam in Loch Modan. Neem hem mee naar het midden van de dam, zodat hij over de reusachtige waterval kan uitkijken.",
  c = "WOW - de dam was VEEL groter dan ik dacht! Ik kon mezelf bijna niet horen praten door het geluid van al dat stromende water! Hé, denk je dat het water ooit opraakt? Jeetje, wat zou er gebeuren als die dam ooit brak! WOW, dat zou eng zijn!$B$BBedankt dat je me de dam hebt laten zien. Dat was heel aardig van je. Ik zei toch dat ik niet te ver voorover zou leunen!",
  e = "Ga naar de top van de Stonewrought Dam in Loch Modan.",
  g = { {"dwergen", "dwarves (dwerg)"}, {"vlakbij", "nearby"}, {"enorme", "huge (enorm)"}, {"uitkijken over", "to look out over"}, {"waterval", "waterfall"}, {"voorover leun", "lean forward (voorover leunen)"}, {"wees", "orphan"}, {"reusachtige", "giant (reusachtig)"}, {"stromende", "rushing, flowing (stromen)"}, {"opraakt", "runs out (opraken)"}, {"jeetje", "man!, gosh"}, {"eng", "scary"} },
},

[1687] = { en = "Spooky Lighthouse", tier = 4,
  t = "De spookvuurtoren",
  d = "Soms vertellen onze verzorgsters in het weeshuis 's avonds laat enge verhalen. Die zijn SUPER! Er is er een over een geest die in een vuurtoren in Westfall spookt. Ze zeggen dat hij een piratenkapitein was, en dat andere piraten zijn schip van hem hebben afgepakt. Wow!$B$BWil je me alsjeblieft naar de vuurtoren in Westfall brengen? Ik wil zien of de geest van die kapitein er is! Ik beloof dat ik dicht bij je blijf; ik ren niet weg of zo!",
  o = "Breng de wees naar de vuurtoren voor de kust van Westfall.",
  c = "WOW, dat was een echte geest! Dat was zo geweldig - ik kan niet wachten om het aan iedereen in het weeshuis te vertellen. Captain Grayson... hij zag er zelfs uit als een piraat! Als ik groot ben, wil ik ook een spookpiraat worden!$B$BBedankt dat je me naar Westfall hebt gebracht, $N. Ik weet dat er enge dingen zijn in de wildernis van Westfall, en ik hoop dat ik niet te lastig was. Je bent geweldig!",
  e = "Ga naar de Westfall Lighthouse.",
  g = { {"spookvuurtoren", "spooky lighthouse"}, {"verzorgsters", "carers, matrons (verzorgster)"}, {"enge", "scary (eng)"}, {"spookt", "haunts (spoken)"}, {"piratenkapitein", "pirate captain"}, {"afgepakt", "taken away (afpakken)"}, {"of zo", "or anything"}, {"voor de kust", "off the coast"}, {"spookpiraat", "ghost pirate"}, {"wildernis", "wilds, wilderness"}, {"lastig", "troublesome, a pain"} },
},

[4822] = { en = "You Scream, I Scream...", tier = 4,
  t = "Jij gilt, ik gil...",
  d = "IJS! O alsjeblieft, alsjeblieft, alsjeblieft, kun je wat ijs voor me halen?! Aardbei is mijn lievelingssmaak, en er is geen beter aardbeienijs in de wereld dan Tigule and Foror's Strawberry Ice Cream! Het is mijn lievelingsijs van de hele wereld!$B$BIk heb het lang geleden één keer gehad, toen ik bij het racecircuit van Shimmering Flats was, maar ik heb gehoord dat ze het nu misschien ook in de stad verkopen! Alsjeblieft? Heel alsjeblieft? Met Tigule and Foror's Strawberry Ice Cream erop??!?!",
  o = "Haal wat Strawberry Ice Cream voor je pupil. De jongen wil blijkbaar het liefst ijs van het merk Tigule and Foror.",
  p = "Ik wou dat ze meer smaken ijs maakten dan alleen aardbei, maar ik heb wel geluk dat aardbei mijn lievelingssmaak is!",
  c = "Mmmmmmmmm! Ik ben dol op hun aardbeienijs! Als Tigule en Foror één ding kunnen, dan is het ijs maken!$B$BHeel erg bedankt, $N - dit is de lekkerste traktatie ooit!",
  g = { {"gilt", "screams (gillen)"}, {"aardbei", "strawberry"}, {"lievelingssmaak", "favourite flavour"}, {"aardbeienijs", "strawberry ice cream"}, {"racecircuit", "race track"}, {"blijkbaar", "apparently"}, {"het liefst", "preferably, most of all"}, {"merk", "brand"}, {"ik wou dat", "I wish"}, {"dol op", "crazy about"}, {"traktatie", "treat"} },
},

[8041] = { en = "Strength of Mount Mugamba", tier = 4,
  t = "De kracht van Mount Mugamba",
  c = "Gegroet, $c. Ik ben Jin'rokh the Breaker, trol van Mugamba. Wij van de Zandalar-stam erkennen wat je hebt bereikt. We groeten je volharding en je wilskracht.$b$bDraag deze talisman om je nek, $c. Laat de kracht van Mount Mugamba door je hele wezen stromen. Laat het je kracht geven wanneer je onze vijanden neerslaat!",
  g = { {"gegroet", "hail, greetings"}, {"stam", "tribe"}, {"erkennen", "to recognise"}, {"bereikt", "accomplished (bereiken)"}, {"volharding", "tenacity, perseverance"}, {"wilskracht", "strength of will"}, {"talisman", "talisman"}, {"wezen", "being"}, {"stromen", "to flow"}, {"neerslaat", "strike down (neerslaan)"} },
},

[8042] = { en = "Strength of Mount Mugamba", tier = 4,
  t = "De kracht van Mount Mugamba",
  p = "Het is goed om te zien dat je in goede gezondheid bent, $n. De glorieuze gevechten die je hebt geleverd, raken al het leven op deze planeet. Hakkar mag de grenzen van Zul'Gurub nooit verlaten, want dan stort de wereld zeker in onder zijn enorme honger.$b$bGeef me je talisman, dan maak ik hem sterker. Gebruik de kracht van Mugamba om onze vijanden te straffen!",
  c = "Onze wegen zullen elkaar weer kruisen, $c.",
  g = { {"gezondheid", "health"}, {"glorieuze", "glorious (glorieus)"}, {"geleverd", "fought, undertaken (een gevecht leveren)"}, {"raken", "to affect, touch"}, {"grenzen", "confines, borders (grens)"}, {"stort in", "collapses (instorten)"}, {"enorme", "immense (enorm)"}, {"straffen", "to punish"}, {"kruisen", "to cross"} },
},

[8043] = { en = "Strength of Mount Mugamba", tier = 4,
  t = "De kracht van Mount Mugamba",
  p = "Meester $n, je bent terug! Molthor heeft de koning bericht gestuurd over je daden. Je naam is zelfs bekend in de South Seas. Misschien word je ooit een legendarische $c - een verhaal voor alle tijden.$b$bGeef me je talisman, zodat ik zijn kracht nog een keer kan versterken.",
  c = "Gebruik je nieuwe kracht om de Gurubashi te vernietigen!",
  g = { {"meester", "master"}, {"bericht gestuurd", "sent word (bericht sturen)"}, {"daden", "deeds (daad)"}, {"legendarische", "legendary (legendarisch)"}, {"voor alle tijden", "for the ages"}, {"versterken", "to amplify, strengthen"}, {"vernietigen", "to destroy"} },
},

[8044] = { en = "The Rage of Mount Mugamba", tier = 4,
  t = "De woede van Mount Mugamba",
  p = "King Rastakhan doet je de groeten, Meester $n. Zo'n eer is nog nooit gegeven aan iemand buiten de Zandalar-stam.$b$b<Jin'rokh buigt.>$b$bGeef me je talisman, zodat ik hem nog een keer kan versterken. Weet dat de woede van Mugamba nu diep verbonden is met je ziel.",
  c = "Zul'jin zou jaloers zijn, $c. Ga voort en verover!",
  g = { {"woede", "rage"}, {"doet je de groeten", "sends his regards (de groeten doen)"}, {"eer", "honour"}, {"buigt", "bows (buigen)"}, {"versterken", "to enhance, strengthen"}, {"verbonden", "connected (verbinden)"}, {"ziel", "soul"}, {"jaloers", "envious, jealous"}, {"ga voort", "go forth (voortgaan)"}, {"verover", "conquer (veroveren)"} },
},

[8045] = { en = "The Heathen's Brand", tier = 4,
  t = "Het brandmerk van de heiden",
  c = "Weet dit, heiden: een ramp heeft ons samengebracht. Jouw heidense gewoonten worden door de Zandalar niet begrepen en niet gewaardeerd, maar we zijn een eerlijk volk. Draag dit brandmerk om je nek. Het zal dienen als waarschuwing voor onze vijanden en als teken van je vriendschap met de Zandalar.$B$BBlijf ons volk dienen, dan zal ik de kracht van het brandmerk versterken.",
  g = { {"brandmerk", "brand"}, {"heiden", "heathen"}, {"ramp", "catastrophe, disaster"}, {"samengebracht", "brought together (samenbrengen)"}, {"heidense", "pagan (heidens)"}, {"gewoonten", "ways, customs (gewoonte)"}, {"gewaardeerd", "appreciated (waarderen)"}, {"eerlijk", "fair, honest"}, {"dienen", "to serve"}, {"waarschuwing", "warning"}, {"teken", "sign, symbol"} },
},

[8046] = { en = "The Heathen's Brand", tier = 4,
  t = "Het brandmerk van de heiden",
  p = "Misschien heb ik te snel geoordeeld, $c. Het lijkt erop dat je blinde geloof in dit Licht toch enige waarde heeft.$B$BGeef me je brandmerk, dan versterk ik zijn kracht.",
  c = "Doe wat je moet doen om onze vijanden te verslaan, $c. Zelfs als dat betekent dat je het Licht gebruikt.$B$B<Jin'rokh huivert.>",
  g = { {"geoordeeld", "judged (oordelen)"}, {"blinde", "blind (blind)"}, {"geloof", "faith"}, {"enige", "some"}, {"waarde", "value"}, {"brandmerk", "brand"}, {"huivert", "shudders (huiveren)"} },
},

[8047] = { en = "The Heathen's Brand", tier = 4,
  t = "Het brandmerk van de heiden",
  p = "Ik moet bekennen dat ik niet dacht dat je de vastberadenheid had om deze zaak tot het einde te brengen, $c. De Zandalar zien je nu als een onmisbare bondgenoot. Heel goed gedaan.$B$BGeef me je brandmerk, dan versterk ik nog een keer zijn kracht.",
  c = "Ons geloof verschilt, maar onze zaak is rechtvaardig. Sla onze vijanden neer, edele $c.",
  g = { {"bekennen", "to confess"}, {"vastberadenheid", "resolution, determination"}, {"zaak", "cause"}, {"onmisbare", "invaluable (onmisbaar)"}, {"bondgenoot", "ally"}, {"verschilt", "differs (verschillen)"}, {"rechtvaardig", "righteous, just"}, {"edele", "noble (edel)"} },
},

[8048] = { en = "The Hero's Brand", tier = 4,
  t = "Het brandmerk van de held",
  p = "De koning heeft erkend dat je bestaat, $c. Je bent de eerste van jouw soort die door Rastakhan aanvaard wordt als echte bondgenoot van de Zandalar.$b$bJe zult rijk beloond worden voor je moeite. Laat je brandmerk zien, dan geef ik het de laatste versterking.",
  c = "Waakzaamheid, eer, trouw, moed... Jij hebt al deze eigenschappen, en dat zal je brandmerk ook hebben.",
  g = { {"erkend", "acknowledged (erkennen)"}, {"soort", "kind"}, {"aanvaard", "accepted (aanvaarden)"}, {"beloond", "rewarded (belonen)"}, {"moeite", "efforts"}, {"versterking", "amplification, strengthening"}, {"waakzaamheid", "vigilance"}, {"trouw", "loyalty"}, {"moed", "bravery, courage"}, {"eigenschappen", "traits (eigenschap)"} },
