[8049] = { en = "The Eye of Zuldazar", tier = 4,
  t = "Het Eye of Zuldazar",
  c = "Neem deze talisman aan als teken van onze waardering, $gpriester:priesteres;.$B$BHet Eye of Zuldazar wordt krachtiger naarmate je band met de trollen van Zandalar sterker wordt. Kom af en toe bij me terug, dan zal ik het juweel met kracht vullen.",
  g = { {"neem aan", "accept (aannemen)"}, {"teken", "token, sign"}, {"waardering", "appreciation"}, {"priesteres", "priestess"}, {"krachtiger", "more powerful"}, {"naarmate", "as (to the degree that)"}, {"band", "bond"}, {"af en toe", "now and then, periodically"}, {"juweel", "jewel"} },
},

[8050] = { en = "The Eye of Zuldazar", tier = 4,
  t = "Het Eye of Zuldazar",
  p = "Welkom, $gpriester:priesteres;. Het Eye of Zuldazar trilt van de energie. Je bent klaar voor de volgende stap. Geef me de talisman, dan vul ik hem met kracht.",
  c = "Ga door met je strijd tegen de Soulflayer en zijn dienaren, $N. Hij mag de grenzen van Zul'Gurub nooit verlaten.",
  g = { {"trilt", "pulses, trembles (trillen)"}, {"stap", "step"}, {"vul", "fill (vullen)"}, {"strijd", "battle, fight"}, {"dienaren", "minions, servants (dienaar)"}, {"grenzen", "confines (grens)"} },
