[8051] = { en = "The Eye of Zuldazar", tier = 4,
  t = "Het Eye of Zuldazar",
  p = "Verhalen over je gevechten tegen de Gurubashi worden in de wind gefluisterd, $gpriester:priesteres;. Zelfs het koningshuis begint over je daden te praten. Er gaat het gerucht dat King Rastakhan je zelfs bij naam heeft genoemd.$B$BHet is tijd om het Eye met kracht te vullen. Geef me de talisman, dan doe ik het voor je.",
  c = "Wees vastberaden in wat je doet, $N. De Soulflayer zal proberen je levenswil weg te zuigen.",
