[8052] = { en = "The All-Seeing Eye of Zuldazar", tier = 4,
  t = "Het All-Seeing Eye of Zuldazar",
  p = "Hadden we er maar tienduizend meer zoals jij, $n. Dan zouden de legers van Hakkar in een oogwenk alle kanten op verspreid zijn.$b$b<Al'tabim zucht.>$b$bHelaas... het Eye is klaar om zijn volle kracht te bereiken. Geef het aan mij.",
  c = "Sla ze allemaal neer en laat Hakkar ze maar uitzoeken...",
  g = { {"hadden we maar", "if only we had"}, {"legers", "armies (leger)"}, {"in een oogwenk", "in the blink of an eye"}, {"verspreid", "scattered (verspreiden)"}, {"zucht", "sighs (zuchten)"}, {"helaas", "alas"}, {"volle kracht", "full potential, full power"}, {"uitzoeken", "to sort out"} },
},

[8734] = { en = "Tyrande and Remulos", tier = 4,
  t = "Tyrande en Remulos",
  d = "Tyrande zal op de hoogte gebracht worden, sterveling. Shan'do Stormrage heeft me op deze mogelijkheid voorbereid.$B$BNu moet je naar Moonglade reizen en met Remulos spreken. Hij zal je verder vertellen hoe Eranikus opgeroepen moet worden.$B$BWe wensen je allemaal veel geluk.",
  o = "Reis naar Moonglade en spreek met Keeper Remulos.",
  c = "Het zou onmogelijk zijn om Eranikus uit de Droom te trekken als hij weigert. Maar zijn plannen dwingen hem om onze wereld binnen te komen. Hij wil de levende vorm van Malfurion vernietigen. Als hem dat lukt, betekent dat het einde van een van de machtigste bondgenoten van de Droom. Als Malfurion valt, zou de Nightmare alles wat er dan nog over is volledig verslinden...",
  g = { {"op de hoogte gebracht", "notified, informed (op de hoogte brengen)"}, {"sterveling", "mortal"}, {"mogelijkheid", "possibility, contingency"}, {"voorbereid", "prepared (voorbereiden)"}, {"opgeroepen", "summoned (oproepen)"}, {"weigert", "refuses (weigeren)"}, {"dwingen", "to force"}, {"levende vorm", "living manifestation, living form"}, {"machtigste", "most powerful (machtig)"}, {"bondgenoten", "allies (bondgenoot)"}, {"volledig", "wholly, completely"}, {"verslinden", "to devour, consume"} },
},

[8763] = { en = "The Hero of the Day", tier = 4,
  t = "De held van de dag",
  d = "Luister... Ik mag je dit eigenlijk niet vertellen, maar omdat jij de held van de dag bent en zo...$B$BIn deze tijd van het jaar ligt er overal verse hulst, maar die blijft nooit lang goed. We hebben een machine die hulst bewaart - hij bederft nooit! We gebruiken hem om de feestdagen wat op te fleuren... en de winst in de zomer!$B$BIk laat je de machine gebruiken, maar alleen als je een meesterkok bent. Je hebt wat Deeprock Salt nodig en twee, drie, laten we zeggen vijf goudstukken. Dan krijg je een mooie partij die je mag houden.",
  o = "Breng 1 Deeprock Salt en 5 goudstukken naar een Holly Preserver-machine. Daar krijg je 5 Preserved Holly.",
  p = "De \"Holly Preserver\"-machine lijkt eerst op een soort distilleerketel, maar als je goed kijkt, zie je dat er dingen aan veranderd zijn op een goblinachtige manier. Toch begrijp je dankzij je kookkunst hoe de machine werkt.$B$BEr zit al verse hulst in de machine. Je hoeft alleen wat Deeprock Salt en vijf goudstukken te geven om de machine aan het werk te zetten.",
  c = "De machine rommelt een beetje en blaast wat stoom uit als hij begint te werken. Niet veel later stopt hij weer, aangekondigd door nog een klein straaltje stoom. Een luikje gaat open, en je ziet een partij bewaarde hulst!",
  g = { {"hulst", "holly"}, {"bederft", "goes bad, spoils (bederven)"}, {"op te fleuren", "to brighten up (opfleuren)"}, {"winst", "profit"}, {"partij", "batch"}, {"distilleerketel", "still (for distilling)"}, {"goblinachtige", "goblin-like"}, {"kookkunst", "cooking skill"}, {"rommelt", "rumbles (rommelen)"}, {"aangekondigd", "announced, heralded (aankondigen)"}, {"straaltje", "small jet"}, {"luikje", "small hatch"} },
