[8860] = { en = "New Year Celebrations!", tier = 4,
  t = "Nieuwjaarsfeest!",
  d = "Stormwind houdt een feest voor het nieuwe jaar! De hele dag kun je vandaag gratis drank krijgen, en 's avonds is er een vuurwerkshow! Het wordt vast heel leuk... maar in Booty Bay is vandaag ook een feest; ik wed dat dat nog beter wordt!$B$BMaar goed, Innkeeper Allison in Stormwind heeft een voorraad eten van Smoky Wood Pasture nodig om alle feestgangers te eten te geven. Wil je me een plezier doen en het bezorgen?$B$BBedankt, $N! Innkeeper Allison is in de Gilded Rose, in het Trade District van Stormwind.",
  o = "Breng de Smokywood Supplies naar Innkeeper Allison in Stormwind.",
  p = "Gegroet! Kom je voor het feest? Of moet je misschien gewoon je vermoeide voeten rust geven...",
  c = "O, mijn Smokywood-voorraad! Prachtig! Die heb ik nodig om alle mensen in de stad te eten te geven tijdens het feest!$B$BDank je, $N. Neem dit alsjeblieft als betaling, en vergeet niet te drinken en te dansen met de feestvierders buiten!",
  g = { {"vuurwerkshow", "fireworks show"}, {"ik wed", "I bet (wedden)"}, {"voorraad", "supply, stock"}, {"feestgangers", "party-goers"}, {"een plezier doen", "to do a favour"}, {"bezorgen", "to deliver"}, {"vermoeide", "weary, tired (vermoeid)"}, {"betaling", "payment"}, {"feestvierders", "revellers"} },
},

[8868] = { en = "Elune's Blessing", tier = 4,
  t = "De zegen van Elune",
  d = "Het beest Omen was ooit een held van deze wereld. Omen was een wolf met grote kracht en veel geluk. Hij vocht naast de helden van de War of the Ancients, tot hij bezweek aan demonische magie. Hij keerde zich tegen zijn bondgenoten, raasde door Azeroth en liet dood en angst achter zich.$B$BOmen werd uiteindelijk hier verslagen, in Moonglade, en nu slaapt hij in het slib van Lake Elune'ara. Maar elk nieuw jaar, tijdens het festival, komt hij in beweging...$B$BVerzamel kameraden, $N, roep het beest Omen op en versla hem. Verdien de zegen van Elune!",
  o = "Roep Omen op, versla hem en ontvang Elune's Blessing. Ga terug naar Valadar Starsong in Nighthaven.",
  p = "Omen beweegt nog altijd onder Lake Elune'ara, $n...",
  c = "Heel goed gedaan, $N. Door Omen te verslaan heb je zijn geest teruggestuurd naar het water van Elune'ara. Het beest zelf is door Elune gezegend en kan dus niet sterven, maar zijn woede zal weer een jaar lang bedaren.",
  e = "Ontvang Elune's Blessing.",
  g = { {"zegen", "blessing"}, {"bezweek", "succumbed (bezwijken)"}, {"demonische", "demonic"}, {"keerde zich tegen", "turned against (zich keren tegen)"}, {"bondgenoten", "allies (bondgenoot)"}, {"raasde", "raged (razen)"}, {"slib", "silt, mud"}, {"komt in beweging", "stirs, starts to move"}, {"kameraden", "comrades (kameraad)"}, {"roep op", "summon (oproepen)"}, {"gezegend", "blessed (zegenen)"}, {"bedaren", "to calm down, subside"} },
},

[8897] = { en = "Dearest Colara,", tier = 4,
  t = "Liefste Colara,",
  d = "Ik moet hier bij de poort de wacht houden, maar ik maak me altijd zorgen om mijn liefje, Colara. Ik zie haar maar een paar uur, als ik geluk heb, en tja, kijk nou naar mij. Ik krijg het loon van een lage officier, en ik kan elke dag naar het front geroepen worden.$b$bZou ze me gewoon vergeten? Er zijn veel mannen in de stad. Veel rijke mannen.$b$bHoe dan ook, ik heb wat dingen opgeschreven... niets bijzonders, maar als je het naar haar kunt brengen, zou dat geweldig zijn.",
  o = "Bezorg Lieutenant Heldric's Carefully Penned Note bij Colara Dean buiten de bank in Stormwind.",
  p = "$gHallo daar, knapperd. Kan ik je ergens mee helpen?:Goh! Kan ik je ergens mee helpen?;",
  c = "O, wat lief! Dit is de eerste keer dat hij me iets stuurt. Denk je dat hij het serieus meent?$b$bColara Heldric? Dat klinkt eigenlijk wel mooi. O, maar ik loop op de zaken vooruit. Dank je.",
  g = { {"de wacht houden", "to keep watch"}, {"liefje", "sweetheart"}, {"loon", "pay, wages"}, {"officier", "officer"}, {"het front", "the front (war)"}, {"hoe dan ook", "anyway"}, {"knapperd", "handsome (man)"}, {"meent het serieus", "is serious about it (menen)"}, {"ik loop op de zaken vooruit", "I'm getting ahead of myself"} },
},

[8898] = { en = "Dearest Colara,", tier = 4,
  t = "Liefste Colara,",
  d = "Ik heb in Stormwind een meisje ontmoet, toen ik daar voor het laatst voor zaken van de bank was. Ze heeft mijn hart gestolen. Nu kan ik niet meer ophouden met aan haar denken! Ik wil haar dit bericht sturen - ik heb het twaalf keer herschreven!$b$bDe post is nu zo vol, en ik wil zeker weten dat het aankomt.$b$bAls je die kant op gaat, kun je me dan helpen?",
  o = "Bezorg de Creased Letter bij Colara Dean buiten de bank in Stormwind.",
  p = "Hallo daar, knapperd. Kan ik je ergens mee helpen?",
  c = "Tormek? O ja, die herinner ik me wel. Hij had een heel mooie baard, met een mooie glimlach eronder.$B$BAh, ik kan niet geloven dat hij me niet vergeten is!",
  g = { {"zaken", "business"}, {"gestolen", "stolen (stelen)"}, {"ophouden", "to stop"}, {"herschreven", "rewritten (herschrijven)"}, {"aankomt", "arrives (aankomen)"}, {"die kant op", "that way"}, {"herinner me", "remember (zich herinneren)"}, {"glimlach", "smile"}, {"eronder", "underneath it"} },
},

[8899] = { en = "Dearest Colara,", tier = 4,
  t = "Liefste Colara,",
  d = "Hoe beschrijf ik haar schoonheid? Duizenden jaren aan woorden, en toch weet ik het niet.$b$bDeze stervelingen brengen de geest in verwarring en maken van ons brabbelende dwazen.$b$bIk heb te lang naar deze woorden gestaard. Ik kan er geen mooiere betekenis meer uit persen. Nee, ze moet het nu krijgen, anders trekt een andere aanbidder vast haar aandacht.",
  o = "Bezorg de Immaculate Letter bij Colara Dean buiten de bank in Stormwind.",
  p = "Hallo daar, knapperd. Kan ik je ergens mee helpen?",
  c = "Zoiets heb ik nog nooit gekregen. Wat mooi!",
  g = { {"schoonheid", "beauty"}, {"stervelingen", "mortals (sterveling)"}, {"verwarring", "confusion"}, {"brabbelende", "babbling (brabbelen)"}, {"dwazen", "fools (dwaas)"}, {"gestaard", "stared (staren)"}, {"persen", "to squeeze, press"}, {"aanbidder", "suitor, admirer"}, {"aandacht", "attention"} },
},

[8903] = { en = "Dangerous Love", tier = 4,
  t = "Gevaarlijke liefde",
  d = "Er is iets onnatuurlijks aan deze epidemie van liefde. Het hoort niet, het is een doorn in het oog, en in het ergste geval kan het een gevaar zijn voor de veiligheid van de Alliance zelf.$b$bDenk eens na: wat als de wachters ook door deze vreemde kwaal gegrepen zijn? Er moet iets gebeuren.$b$bGa naar een van de wachters hier in Stormwind en kijk of zij ook in deze dwaasheid zijn meegesleept.",
  o = "Haal een Stormwind Guard's Card en breng die terug naar Aristan Mottar in Stormwind.",
  p = "Maakte ik me terecht zorgen? Zijn de wachters getroffen door deze liefdesziekte?",
  c = "Het is dus waar. Dit is ongelooflijk. Hoe heeft dit kunnen gebeuren? Laat me even nadenken. Er moet een reden achter zitten.",
  g = { {"onnatuurlijks", "unnatural (onnatuurlijk)"}, {"het hoort niet", "it's not proper"}, {"een doorn in het oog", "an eyesore"}, {"in het ergste geval", "at worst"}, {"kwaal", "affliction, ailment"}, {"gegrepen", "seized, taken (grijpen)"}, {"dwaasheid", "foolishness"}, {"meegesleept", "carried away (meeslepen)"}, {"terecht", "rightly"}, {"getroffen", "struck, afflicted (treffen)"}, {"liefdesziekte", "lovesickness"}, {"ongelooflijk", "unbelievable"} },
},

[8993] = { en = "Gift Giving", tier = 4,
  t = "Cadeaus geven",
  p = "Kom je een cadeau van liefde en bewondering brengen voor je favoriete leider?",
  c = "Geweldig! Geweldig! Ik leg dit bij de stapel andere cadeaus.$b$bIk had er niet zo veel verwacht! Je moet echt van je leiders houden.$b$bZo, laat me er nog eentje bij tellen...",
  g = { {"bewondering", "adoration, admiration"}, {"favoriete", "favourite"}, {"stapel", "pile"}, {"verwacht", "expected (verwachten)"}, {"bij tellen", "to add to the count (bijtellen)"} },
},

[9024] = { en = "Aristan's Hunch", tier = 4,
  t = "Aristans vermoeden",
  d = "Ik heb het! Heb je de nieuwe geur in de wind geroken? De nieuwe eau de colognes en parfums die in de mode zijn gekomen? Onze wachters zouden hun plichten niet zo makkelijk verwaarlozen.$b$bTenminste, niet als hun denken niet vertroebeld is door een of andere smerige alchemie.$b$bEr is maar één manier om het zeker te weten: breng een fles eau de cologne en een fles parfum naar Morgan Pestle, en vertel hem wat ik vermoed. Als je terugkomt, betaal ik je terug wat je ervoor hebt uitgegeven.",
  o = "Breng 1 Cologne Bottle en 1 Perfume Bottle naar Morgan Pestle in het Trade District van Stormwind.",
  p = "Kan ik je ergens mee helpen?",
  c = "Ik begrijp Aristans zorgen, maar ik denk echt dat hij overdrijft. Laat jonge mannen en vrouwen toch doen wat ze willen. Ik denk dat Aristan vergeten is wat het betekent om jong en verliefd te zijn.$b$bMaar dat kunnen we hem beter niet vertellen. We gaan er maar in mee.",
  g = { {"vermoeden", "hunch, suspicion"}, {"geur", "smell, fragrance"}, {"in de mode", "in fashion"}, {"plichten", "duties (plicht)"}, {"verwaarlozen", "to neglect"}, {"vertroebeld", "clouded (vertroebelen)"}, {"smerige", "foul, dirty (smerig)"}, {"vermoed", "suspect (vermoeden)"}, {"uitgegeven", "spent (uitgeven)"}, {"overdrijft", "exaggerates, overreacts (overdrijven)"}, {"verliefd", "in love"}, {"we gaan er maar in mee", "we'll just humour him"} },
},

[9025] = { en = "Morgan's Discovery", tier = 4,
  t = "Morgans ontdekking",
  d = "Nou ja, zeg. Het lijkt erop dat Aristan toch iets op het spoor is. Ik heb sporen gevonden van stoffen die gebruikt worden in liefdesdrankjes en in verraderlijke drankjes die de geest veranderen.$b$bHet is niet ongewoon dat parfums daar wat van bevatten, maar een paar van de ingrediënten die ik gevonden heb... Daar zit een luchtje aan.",
  o = "Ga terug naar Aristan Mottar buiten de bank in het Trade District van Stormwind.",
  c = "Ik dacht al dat het zo zou zijn, maar het blijft verontrustend dat mijn vermoedens klopten. We moeten goed nadenken over onze volgende stap.$b$bHier, dit is om je terug te betalen voor de eau de cologne en de parfum.",
  g = { {"ontdekking", "discovery"}, {"nou ja, zeg", "well, I'll be"}, {"op het spoor", "on to (something)"}, {"sporen", "traces (spoor)"}, {"stoffen", "substances (stof)"}, {"liefdesdrankjes", "love potions"}, {"verraderlijke", "insidious, treacherous (verraderlijk)"}, {"ongewoon", "unusual"}, {"bevatten", "to contain"}, {"daar zit een luchtje aan", "something smells fishy about it"}, {"verontrustend", "unsettling"}, {"vermoedens", "suspicions (vermoeden)"}, {"klopten", "were right (kloppen)"} },
},

[9026] = { en = "Tracing the Source", tier = 4,
  t = "Op zoek naar de bron",
  d = "We moeten de bron vinden. Ik heb veel meer mensen dan normaal - ook wachters - in en uit The Gilded Rose zien gaan. Praat met Allison. Als zij ze verkoopt, kan ze je vertellen waar ze vandaan komen.",
  o = "Spreek met Innkeeper Allison in The Gilded Rose in het Trade District van Stormwind.",
  c = "O ja, ik heb de parfum en eau de cologne pas net binnengekregen. Het verkoopt zo goed dat ik niet weet hoe lang ik het nog in de schappen kan houden.$b$bAls je het mij vraagt, is het eigenlijk een beetje saai. Iedereen die hetzelfde ruikt? Het ruikt heerlijk, maar toch.",
  g = { {"bron", "source"}, {"vandaan", "from (where)"}, {"binnengekregen", "got in (stock) (binnenkrijgen)"}, {"schappen", "shelves (schap)"}, {"als je het mij vraagt", "if you ask me"}, {"saai", "boring"}, {"ruikt", "smells (ruiken)"}, {"maar toch", "but still"} },
},

[9027] = { en = "Tracing the Source", tier = 4,
  t = "Op zoek naar de bron",
  d = "Is er iets vreemds met de eau de cologne? Dat kan. Ik heb nog nooit zoveel mensen achter één product aan zien gaan.$b$bKijk, als er iets mis mee is, wil ik dat ook weten. Ik heb mijn voorraad gekocht van een koopman die Evert Sorisam heet. Hij is nieuw in de stad.$b$bHij zei dat hij wat goederen had die hij naar The Finest Thread ging brengen.",
  o = "Spreek met Evert Sorisam in The Finest Thread langs de kanalen van Stormwind.",
  c = "Ja, natuurlijk. Die geuren zijn dit seizoen de populairste artikelen. Je bent vast de vijfde of zesde persoon dit uur die ernaar vraagt.$b$bIk ben bang dat mijn voorraad helemaal uitverkocht is. Als je wat wilt, moet je met Allison praten, de waardin van The Gilded Rose.$b$bVerspil wel geen tijd. Ik denk dat je de $geau de cologne:parfum; onweerstaanbaar zult vinden.",
  g = { {"vreemds", "strange (vreemd)"}, {"achter aan gaan", "to go after (achter iets aan gaan)"}, {"mis", "wrong"}, {"koopman", "merchant"}, {"goederen", "goods"}, {"kanalen", "canals (kanaal)"}, {"artikelen", "items, articles (artikel)"}, {"uitverkocht", "sold out"}, {"waardin", "innkeeper (f.)"}, {"verspil", "waste (verspillen)"}, {"onweerstaanbaar", "irresistible"} },
},

[9028] = { en = "The Source Revealed", tier = 4,
  t = "De bron onthuld",
  d = "Wat? Verraad? Nee, nee. Ik verzeker je dat mijn bedoelingen volkomen onschuldig zijn.$b$bIs het zo verkeerd om mensen te helpen die het pijnlijke ritueel van het hofmaken makkelijker willen maken? Kom, dat is toch geen misdaad.$b$bEn om te bewijzen dat ik geen kwaad wil, vertel ik je zelfs wie mijn leverancier is.$b$bZe werden naar me verscheept door een zekere Staffron Lerent, een soort apotheker. Ik heb nooit met hem gesproken.$b$bOnze goblin-tussenpersoon zei dat hij werkte in de heuvels boven Hillsbrad, voorbij dat geheimzinnige Ravenholdt Manor. Ik wens je veel geluk als je hem gaat zoeken.",
  o = "Zoek Apothecary Staffron Lerent in de Hillsbrad Foothills achter Ravenholdt Manor.",
  c = "Ja, ik heb die geuren gemaakt. Heerlijke geur, nietwaar? Onweerstaanbaar.$b$bZodra de krijgers van de Alliance en de Horde allemaal door deze gevoelens van liefde getroffen zijn, zullen ze machteloos zijn om de opkomst van de Shadow Council tegen te houden.$b$bZe zullen verzwakt zijn en onvoorbereid. Terwijl ze zich zorgen maken om hun geliefden, raken ze hun scherpte kwijt.$b$bDe oplossing was zo simpel. Waarom duurde het zo lang voordat ik erop kwam? Ieders zwakte ligt in het hart. En er is niets wat je kunt doen om het onvermijdelijke tegen te houden.",
  g = { {"onthuld", "revealed (onthullen)"}, {"verraad", "treason"}, {"verzeker", "assure (verzekeren)"}, {"bedoelingen", "intentions (bedoeling)"}, {"onschuldig", "harmless, innocent"}, {"het hofmaken", "courtship"}, {"leverancier", "supplier"}, {"verscheept", "shipped (verschepen)"}, {"apotheker", "apothecary"}, {"tussenpersoon", "middleman"}, {"geheimzinnige", "mysterious (geheimzinnig)"}, {"machteloos", "powerless"}, {"opkomst", "rise"}, {"onvoorbereid", "unprepared"}, {"scherpte", "edge, sharpness"}, {"het onvermijdelijke", "the inevitable"} },
},

