[9267] = { en = "Mending Old Wounds", tier = 4,
  t = "Oude wonden helen",
  p = "Je kunt maar beter twee keer nadenken voordat je een voet in Ratchet zet, $n! Er gaan verhalen rond over je smerige daden.$b$bMaar je hebt geluk: er is net een schip aangekomen met veel gewonden na een gevecht met de Bloodsail Buccaneers. Dit is je kans om te bewijzen dat je geen volslagen schurk bent. Help ons een handje door linnen stof te brengen voor verband en lege flesjes voor drankjes.",
  c = "Ik ben blij dat je inziet wat je fout hebt gedaan, $N. Blijf de spullen brengen; we vergeten je niet zo snel, $Gmeneer:juffrouw;!",
  g = { {"wonden", "wounds (wond)"}, {"helen", "to heal, mend"}, {"je kunt maar beter", "you'd better"}, {"er gaan verhalen rond", "word is getting around"}, {"smerige daden", "dirty deeds"}, {"gewonden", "wounded people"}, {"volslagen", "complete, utter"}, {"schurk", "scoundrel"}, {"help een handje", "lend a hand (een handje helpen)"}, {"linnen stof", "linen cloth"}, {"verband", "bandages"}, {"flesjes", "vials, small bottles (flesje)"}, {"inziet", "realise, see (inzien)"}, {"juffrouw", "miss"} },
},

})

